package ma.translogix.model;

import java.time.LocalDate;

/** An employee of the company ([M2]). A driver is an Employe with poste CHAUFFEUR. */
public class Employe {
    private Long id;
    /** MAT-YYYY-NN, generated by EmployeService, never changed. */
    private String matricule;
    private String nom;
    private String prenom;
    private String cin;
    private String cnss;
    private Poste poste;
    private TypeContrat typeContrat;
    private LocalDate dateEmbauche;
    private boolean actif = true;
    /** Optional login account (Utilisateur.id); null when the employee has no account. */
    private Long utilisateurId;

    public Employe() {
    }

    public Employe(Long id, String matricule, String nom, String prenom, String cin, String cnss, Poste poste,
                   TypeContrat typeContrat, LocalDate dateEmbauche, boolean actif, Long utilisateurId) {
        this.id = id;
        this.matricule = matricule;
        this.nom = nom;
        this.prenom = prenom;
        this.cin = cin;
        this.cnss = cnss;
        this.poste = poste;
        this.typeContrat = typeContrat;
        this.dateEmbauche = dateEmbauche;
        this.actif = actif;
        this.utilisateurId = utilisateurId;
    }

    public String getNomComplet() {
        return prenom + " " + nom;
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public String getMatricule() { return matricule; }
    public void setMatricule(String matricule) { this.matricule = matricule; }

    public String getNom() { return nom; }
    public void setNom(String nom) { this.nom = nom; }

    public String getPrenom() { return prenom; }
    public void setPrenom(String prenom) { this.prenom = prenom; }

    public String getCin() { return cin; }
    public void setCin(String cin) { this.cin = cin; }

    public String getCnss() { return cnss; }
    public void setCnss(String cnss) { this.cnss = cnss; }

    public Poste getPoste() { return poste; }
    public void setPoste(Poste poste) { this.poste = poste; }

    public TypeContrat getTypeContrat() { return typeContrat; }
    public void setTypeContrat(TypeContrat typeContrat) { this.typeContrat = typeContrat; }

    public LocalDate getDateEmbauche() { return dateEmbauche; }
    public void setDateEmbauche(LocalDate dateEmbauche) { this.dateEmbauche = dateEmbauche; }

    public boolean isActif() { return actif; }
    public void setActif(boolean actif) { this.actif = actif; }

    public Long getUtilisateurId() { return utilisateurId; }
    public void setUtilisateurId(Long utilisateurId) { this.utilisateurId = utilisateurId; }
}
